// 由 tools/bake_dealer.js 產生，不准手改：JOJO 荷官五種表情烘焙過光影的點陣圖（WebP，品質 0.92）。
// 走 data: URL 是因為 file:// 下外部圖檔上傳 WebGL 會被當成跨來源擋掉（2026-11-07 Edge 實測 SecurityError）。
// source 是烘焙當時 SVG 的雜湊：dealer.js 的畫改了卻沒重跑烘焙，tests/check_dealer.js 會紅
(function () {
  const V = window.BJK.view;
  V.dealerBaked = {
    hash: s => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); },
    source: {"idle":"74ebd57b","deal":"cbf26697","surprised":"3e857fd3","smile":"2d0f090d","sorry":"2a258842"},
    images: {
      idle: 'data:image/webp;base64,',
      deal: 'data:image/webp;base64,',
      surprised: 'data:image/webp;base64,',
      smile: 'data:image/webp;base64,',
      sorry: 'data:image/webp;base64,',
    },
  };
})();
